const cap1=s=>up(s.charAt(0))+s.slice(1);
// Season progress: current game, record, and one tick per game (green win, red loss, outlined next).
function tracker(){if(!state)return '';const n=state.schedule.length,done=state.results.length,cur=Math.min(n,closingMatch?state.results.at(-1).week+1:state.week+1);const ticks=state.schedule.map((g,i)=>{const r=state.results[i],cls=r?(r.home>r.away?'w':'l'):i===state.week&&!state.finished?'next':'',title=r?t('tracker.tickResult',{n:i+1,outcome:t(r.home>r.away?'result.win':'result.loss'),home:r.home,away:r.away}):t('tracker.tick',{n:i+1});return `<i class="${cls}" title="${esc(title)}"></i>`;}).join('');
 return `<div class="game-tracker" role="group" aria-label="${esc(state.finished?t('tracker.completeAria'):t('tracker.aria',{cur,n}))}"><div class="gt-top"><span>${state.finished?tu('tracker.complete'):tu('tracker.game')}</span><b>${state.wins}–${state.losses}<em>${tu('metrics.record')}</em></b></div><strong>${state.finished?n:cur}<small>/ ${n}</small></strong><div class="gt-ticks" style="--n:${n}" aria-hidden="true">${ticks}</div><div class="gt-foot"><span>${t('tracker.played',{n:done})}</span><span>${t('tracker.left',{n:Math.max(0,n-done)})}</span></div></div>`;}
/* ESPN-style season leaders: category, player, per-game value. */
const hasScore=g=>Number.isInteger(g?.points)&&Number.isInteger(g?.against);
/* Where estimated player stats come from: this season's final scores once any exist, else last season's average. */
const estSrc=()=>state?.schedule?.some(hasScore)?"the team's real scoring":"the team's 2025–26 scoring";
function leadersCard(){const L=E.leaders(state);return `<section class="card leaders-card"><span class="eyebrow">${tu('leaders.title',{team:esc(teamLabel())})}</span><ul class="leaders">${['ppg','apg','rpg','bpg','spg'].map(k=>{const l=L[k];return `<li><b>${t(`leaders.${k}`)}:</b> ${l?t('leaders.value',{name:`<button class="leader-link" data-action="player" data-id="${l.id}">${esc(l.name)}</button>`,value:l.value.toFixed(1)}):`<span class="muted">${t('leaders.none')}</span>`}</li>`;}).join('')}</ul><small class="muted">
${L.est?`Estimates built from ${estSrc()}. Your stats take over after the first game.`:'Simulated statistics from your season.'}</small>
</section>`;}
/* ESPN-style box score: starters, bench, team totals. */
function boxTable(line,title,compact=false){if(!line)return '';const rows=Object.entries(line).map(([id,l])=>({p:state.players.find(p=>p.id===+id),l})).filter(x=>x.l.min>0||x.l.fga||x.l.reb||x.l.ast||x.l.stl||x.l.blk||x.l.tov);if(!rows.length)return '';const tot=rows.reduce((s,{l})=>{for(const k of ['min','pts','reb','ast','stl','blk','fgm','fga','tpm','tpa','tov'])s[k]=(s[k]||0)+(l[k]||0);return s;},{});const cells=l=>compact?`<td><b>${l.pts}</b></td><td>${l.reb}</td><td>${l.ast}</td><td>${l.stl}</td><td>${l.blk}</td>`:`<td>${l.min??'—'}</td><td><b>${l.pts}</b></td><td>${l.fgm}-${l.fga}</td><td>${l.tpm}-${l.tpa}</td><td>${l.reb}</td><td>${l.ast}</td><td>${l.stl}</td><td>${l.blk}</td><td>${l.tov}</td>`;const heads=(compact?['pts','reb','ast','stl','blk']:['min','pts','fg','tp','reb','ast','stl','blk','to']).map(h=>t(`box.${h}`));const group=(name,list)=>list.length?`<tr class="box-group"><td>${name}</td>${heads.map(h=>`<td>${esc(h)}</td>`).join('')}</tr>${list.map(({p,l})=>`<tr><td class="box-player"><span class="box-name">${esc(p?.name??t('result.former'))}</span> <span class="box-pos">${p&&p.position[0]!=='N'?esc(p.position[0])+' ':''}#${p?.number??''}</span></td>${cells(l)}</tr>`).join('')}`:'';return `<div class="table-wrap box-score${compact?' compact':''}"><table><caption>${esc(title)}</caption><tbody>${group(tu('box.starters'),rows.filter(x=>x.l.start))}${group(tu('box.bench'),rows.filter(x=>!x.l.start))}<tr class="box-total"><td class="box-player">${tu('box.team')}</td>${cells(tot)}</tr></tbody></table></div>`;}
const TOAST_ICONS={success:'<path d="M5 12.5l4.2 4.2L19 7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.01"/>',error:'<path d="M12 3l9.5 17h-19z"/><path d="M12 10v4.5M12 17.5v.01"/>',warn:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 16.5v.01"/>',staff:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-4 3.6-6 7-6s6.2 2 7 6"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3v18M5.6 5.6c3 3 3 9.8 0 12.8M18.4 5.6c-3 3-3 9.8 0 12.8"/>',film:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M10 9.5l5 2.5-5 2.5z"/>'};
// Notification cards: a few at a time, each dismissable, paused while hovered. The text and the title are already in the player's language.
function notify(msg,opt={}){const box=$('#toast');if(!box)return;const type=opt.type||'info',ms=opt.ms??(getA11y().timingAssist?12000:type==='error'?6500:5200);const card=document.createElement('div');card.className=`toast-card ${type}`;card.setAttribute('role',type==='error'?'alert':'status');card.style.setProperty('--life',ms+'ms');
 card.innerHTML=`<span class="toast-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${TOAST_ICONS[opt.icon]||TOAST_ICONS[type]}</svg></span><div class="toast-body"><b>${esc(opt.title||t(`toast.${type}`))}</b><p>${esc(msg)}</p>${opt.chips?.length?`<div class="toast-chips">${opt.chips.map(c=>`<span class="${/^[−-]/.test(c)?'down':'up'}">${esc(c)}</span>`).join('')}</div>`:''}</div><button type="button" class="toast-close" aria-label="${esc(t('toast.dismiss'))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button><i class="toast-timer" aria-hidden="true"></i>`;
 const kill=()=>{if(card.dataset.out)return;card.dataset.out=1;card.classList.add('out');setTimeout(()=>{card.remove();if(!box.children.length&&box.hidePopover&&box.matches(':popover-open'))box.hidePopover();},260);};
 let left=ms,start=Date.now(),timer=setTimeout(kill,left);card.addEventListener('mouseenter',()=>{clearTimeout(timer);left-=Date.now()-start;card.classList.add('hold');});card.addEventListener('mouseleave',()=>{start=Date.now();card.classList.remove('hold');timer=setTimeout(kill,Math.max(900,left));});card.querySelector('.toast-close').addEventListener('click',e=>{e.stopPropagation();clearTimeout(timer);kill();});
 box.prepend(card);[...box.children].slice(3).forEach(c=>c.remove());if(box.showPopover){try{if(box.matches(':popover-open'))box.hidePopover();box.showPopover();}catch{}}}
const signed=(n,unit)=>`${n>0?'+':'−'}${Math.abs(Math.round(n))} ${unit}`;
// After a coaching action: the decision-trail line plus what it cost or gained.
function actionToast(a,was){if(!state)return;const msg=state.log[0]?logText(state.log[0]):t('notify.saved'),chips=[];if(was){const dt=state.tokens-was.tokens,ds=state.actions-was.actions,dc=state.chemistry-was.chemistry;if(dt)chips.push(signed(dt,t('toast.tokens')));if(ds)chips.push(signed(ds,t(Math.abs(ds)===1?'toast.slot':'toast.slots')));if(dc)chips.push(signed(dc,t('toast.chemistry')));}
 if(a==='hire'){const c=E.staff.find(x=>x.key===state.assistant);return notify(c?t('toast.hired',{name:t(`staff.${c.key}.name`),detail:cap1(t(`staff.${c.key}.detail`))}):msg,{type:'success',icon:'staff',title:t('toast.hiredTitle'),chips});}
 const map={train:['train','success','ball'],recruit:['recruit','success','staff'],talk:['talk','success','staff'],scout:['scout','success','film'],release:['release','warn','staff'],dismiss:['dismiss','warn','staff']};const [key,type,icon]=map[a]||['saved','success'];notify(msg,{title:t(`toast.titles.${key}`),type,icon,chips});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify(t('notify.storage'),{type:'warn',title:t('toast.storageTitle')});}}
function show(html){arena.paused=true;modal.innerHTML=`${btn('×','close','close',`aria-label="${esc(t('a11y.closeDialog'))}"`)}<div class="modal-content">${html}</div>`;const h=modal.querySelector('h1');if(h){h.id='modal-title';modal.setAttribute('aria-labelledby','modal-title');}if(!modal.open)modal.showModal();}
const settings=createSettingsDialog({modal,show,notify,onKeysChange:k=>{keys=k;render();}});
function openSettings(tab){settings.open(tab);}
function toggleSound(){const muted=!getSound().muted;setSound({muted});if(!muted)play('select');announce(muted?t('a11y.soundOff'):t('a11y.soundOn'));}
function toggleMotion(){const reduced=getA11y().reducedMotion;setA11y({reducedMotion:!reduced});announce(reduced?t('a11y.motionOn'):t('a11y.motionOff'));}
const speedLabel=n=>`${n}×`;
function applyArena(){const a=getA11y();arena.motion=!a.reducedMotion;arena.shakeOn=a.screenShake;arena.speed=playbackSpeed*a.playbackSpeed;}
applyArena();
function stage(cls=''){const cams=[['auto','camAuto','stage.auto','stage.autoTitle'],['broadcast','camWide','stage.wide'],['court','camCourt','stage.court'],['follow','camFollow','stage.follow'],['player','camPlayer','stage.player','stage.playerTitle']];return `<div id="arena" class="${cls}" role="group" aria-label="${esc(t('a11y.stage'))}"><div class="arena-top">${pill('● '+tu('stage.venue'),'live')}<span class="orbit-hint">${micon('drag')}${t('stage.orbit')}${micon('scroll')}${t('stage.zoom')}</span></div>${cls.includes('game-arena')?'<div class="fp-hud" role="status" aria-live="polite" hidden></div>':''}<div class="arena-bottom"><div><span class="eyebrow">${tu('stage.place')}</span><h3 class="live-action">${t('stage.tagline')}</h3></div><div class="camera-controls" role="group" aria-label="${esc(t('stage.camera'))}">${cams.map(([v,k,l,d])=>btn(t(l),'camera',arena.mode===v?'active':'',`data-camera="${v}" aria-pressed="${arena.mode===v}" ${hint(k,d?t(d):'')}`)).join('')}</div></div></div>`;}
function meters(){return `<div class="metrics">${[[t('metrics.record'),`${state.wins}–${state.losses}`],[t('metrics.tokens'),formatNumber(state.tokens)],[t('metrics.chemistry'),`${Math.round(state.chemistry)}%`],[t('metrics.fans'),formatNumber(state.fans)]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`;}
function header(kicker,title,description=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1 tabindex="-1">${title}</h1>${description?`<p>${description}</p>`:''}</div>${tracker()}</div>`;}
function landing(){return `<main class="landing" id="main"><div class="landing-brand"><img class="brand-logo" src="${LOGO}" alt="" width="58" height="43"><div>${tu('landing.school')} <span>${tu('landing.program')}</span></div>${pill(tu('landing.badge'))}</div><div class="landing-content"><div class="landing-copy"><div class="eyebrow"><span class="line"></span> ${tu('landing.tagline')}</div><h1 tabindex="-1">${tu('landing.titleA')}<br><em>${tu('landing.titleB')}</em></h1><p>${t('landing.intro')}</p><form id="start-form"><label for="coach">${tu('landing.name')}</label><input id="coach" name="coach" maxlength="32" placeholder="${esc(t('landing.namePlaceholder'))}" required autocomplete="given-name"><div class="difficulty"><label for="difficulty">${tu('landing.challenge')}</label><select id="difficulty" name="difficulty">${Object.keys(E.DIFFICULTIES).map(k=>`<option value="${k}" ${k==='standard'?'selected':''}>${t(`difficulty.${k}`)}</option>`).join('')}</select></div><button class="primary launch" type="submit">${t('landing.start')} <span aria-hidden="true">↗</span></button></form>${state?btn(t('landing.continue'),'continue','secondary wide'):''}<div class="landing-links">${btn(t('landing.howTo'),'rules')}${btn(t('side.credits'),'credits')}${btn(t('landing.import'),'import')}${btn(t('top.settings'),'settings',' ',hint('settings'))}</div></div><div class="landing-visual">${stage('title-arena')}<div class="season-ticket"><span>${tu('landing.ticketSeason',{season:esc((data?.season??'2026–27').replace('–','—'))})}</span><strong>${tu('landing.ticketA')}<br>${tu('landing.ticketB')}</strong><div>${data?.levels?t('landing.ticketReal',{players:Object.values(data.levels).reduce((a,x)=>a+x.players.length,0),games:Object.values(data.levels).reduce((a,x)=>a+x.games.length,0)}):t('landing.ticketFallback')}<br>${t('landing.ticketTail')}</div></div></div></div><footer>${tu('landing.footer')} <span>${tu('landing.footerNote')}</span></footer></main>`;}
function home(){const opp=!state.finished?E.opponent(state):null,last=state.results.at(-1),P=plan(),names=stages();return `${header(tu('home.kicker'),t('home.welcome',{name:esc(state.coach)}),state.finished?t('home.doneIntro'):t('home.intro'))}${meters()}<div class="hq-grid"><div>${stage()}<div class="quick-grid">${[['roster',tu('home.quickRosterA'),t('home.quickRosterB'),'↗'],['practice',tu('home.quickPracticeA'),t('home.quickPracticeB',{n:state.actions}),'↗'],['staff',tu('home.quickStaffA'),t('home.quickStaffB'),'↗']].map(([v,a,b,c])=>`<button class="quick" data-view="${v}"><span>${a}</span><strong>${b}</strong><i aria-hidden="true">${c}</i></button>`).join('')}</div></div><aside class="right-rail" aria-label="${esc(t('home.sidebar'))}"><section class="card next-game"><span class="eyebrow">${state.finished?tu('home.finalChapter'):tu('home.nextOnSchedule')}</span>${state.finished?`<div class="matchup solo"><img src="${LOGO}" alt="${esc(t('game.kangs'))}"></div>`:`<div class="matchup"><img src="${LOGO}" alt="${esc(t('game.kangs'))}"><span aria-hidden="true">${tu('home.vs')}</span>${oppMark(opp.opponent,'opp-logo',`<b class="opp-crest" aria-hidden="true">${esc(crestText(opp.opponent))}</b>`)}</div>`}<h2>${state.finished?(state.champion?t('home.champions'):t('home.seasonEnds')):esc(opp.opponent)}</h2><p>${state.finished?t('home.finalRecord',{w:state.wins,l:state.losses}):`${esc(formatDate(opp.date))} · ${esc(opp.venue)}`}</p>${btn(state.finished?t('home.viewStory'):t('home.prepare'),state.finished?'journal':'game','primary wide')}<small>${state.week>=P.cut?tu('home.bracketNote',{run:names.run}):tu('home.seasonNote',{team:teamLabel()})}</small></section>${leadersCard()}<section class="card"><span class="eyebrow">${tu('home.rippleKicker')}</span><h3>${t('home.rippleTitle')}</h3><p>${esc(state.ripples[0]?logText(state.ripples[0]):t('home.rippleDefault'))}</p>${last?`<div class="mini-result"><span aria-hidden="true">${last.won?'W':'L'}</span> <strong>${last.home}–${last.away}</strong> ${esc(last.opponent)}<span class="sr-only"> (${last.won?t('result.win'):t('result.loss')})</span></div>`:''}</section></aside></div>`;}
const SKIN=['#f1c7a3','#e0a87e','#c68a5e','#a86f45','#8a5634','#6b3f24','#4f2c19','#d9a07a'];
const HAIR=['#17110d','#2a1b12','#3d2616','#5b3a22','#8a5a2e','#b9874a','#d8b06a','#20180f'];
function avatar(p,size=48){const h=E.hashStr((p.originalName||p.name)+'|'+p.id),g=n=>(h>>>n),skin=SKIN[g(1)%SKIN.length],hair=HAIR[(g(4)+(SKIN.indexOf(skin)>3?0:2))%HAIR.length],style=(g(7)+p.id)%7,rx=21+g(11)%4,ry=26+g(13)%3,band=g(16)%6===0,beard=['Junior','Senior'].includes(p.year)&&g(18)%3===0,kit=state?.kit==='away'?['#f4effc','#562494']:state?.kit==='alternate'?['#191126','#e9b858']:['#6832ab','#ffffff'],uid='a'+h.toString(36)+p.id;
 const top=60-ry,shade=`color-mix(in srgb,${skin} 78%,#000)`;
 const hairSvg=[
  `<path d="M${60-rx} ${58-ry*.15}Q${60-rx} ${top-3} 60 ${top-3}Q${60+rx} ${top-3} ${60+rx} ${58-ry*.15}Q${60+rx-3} ${top+8} 60 ${top+6}Q${60-rx+3} ${top+8} ${60-rx} ${58-ry*.15}Z" fill="${hair}" opacity=".9"/>`,
  `<path d="M${60-rx+1} ${top+14}L${60-rx+2} ${top-14}Q60 ${top-20} ${60+rx-2} ${top-14}L${60+rx-1} ${top+14}Q60 ${top+4} ${60-rx+1} ${top+14}Z" fill="${hair}"/>`,
  `<g fill="${hair}">${[-16,-8,0,8,16,-12,-4,4,12].map((x,k)=>`<circle cx="${60+x}" cy="${top+(k<5?2:-5)}" r="${7.5}"/>`).join('')}</g>`,
  `<path d="M${60-rx} ${top+16}Q${60-rx} ${top-4} 60 ${top-4}Q${60+rx} ${top-4} ${60+rx} ${top+16}Q60 ${top+6} ${60-rx} ${top+16}Z" fill="${hair}"/><path d="M${60-rx+5} ${top+6}q6 -3 12 0t12 0t12 0" stroke="${skin}" stroke-opacity=".25" fill="none"/>`,
  `<path d="M${60-rx-1} ${top+20}Q${60-rx-2} ${top-6} 60 ${top-5}Q${60+rx+3} ${top-5} ${60+rx+1} ${top+18}Q${60+4} ${top+4} ${60-rx-1} ${top+20}Z" fill="${hair}"/>`,
  `<ellipse cx="60" cy="${top+10}" rx="${rx+9}" ry="${ry*.75}" fill="${hair}"/>`,
  `<path d="M${60-rx} ${top+18}Q${60-rx} ${top-2} 60 ${top-2}Q${60+rx} ${top-2} ${60+rx} ${top+18}L${60+rx-2} ${top+9}Q60 ${top+3} ${60-rx+2} ${top+9}Z" fill="${hair}"/><path d="M${60-rx+2} ${top+10}Q${60-rx-6} ${top+26} ${60-rx-1} ${top+34}M${60+rx-2} ${top+10}Q${60+rx+6} ${top+26} ${60+rx+1} ${top+34}" stroke="${hair}" stroke-width="5" fill="none" stroke-linecap="round"/>`][style];
 const behind=style===5?hairSvg:'',front=style===5?`<path d="M${60-rx+2} ${top+12}Q60 ${top+2} ${60+rx-2} ${top+12}" stroke="${hair}" stroke-width="6" fill="none"/>`:hairSvg;
 return `<svg class="avatar" width="${size}" height="${size*7/6}" viewBox="0 0 120 140" role="img" aria-label="${esc(p.name)} avatar"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b2160"/><stop offset="1" stop-color="#140c20"/></linearGradient></defs><rect width="120" height="140" rx="14" fill="url(#${uid})"/>${behind}
  <path d="M8 140C12 110 32 100 60 100S108 110 112 140Z" fill="${kit[0]}"/><path d="M44 101L60 118L76 101" fill="none" stroke="${kit[1]}" stroke-width="4"/><text x="60" y="137" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="800" font-size="20" fill="${kit[1]}">${esc(p.number)}</text>
  <rect x="51" y="78" width="18" height="26" rx="6" fill="${shade}"/><ellipse cx="${60-rx}" cy="62" rx="4" ry="6" fill="${shade}"/><ellipse cx="${60+rx}" cy="62" rx="4" ry="6" fill="${shade}"/><ellipse cx="60" cy="60" rx="${rx}" ry="${ry}" fill="${skin}"/>${front}
  ${band?`<rect x="${60-rx}" y="${top+12}" width="${rx*2}" height="6" rx="3" fill="${kit[0]}" stroke="${kit[1]}" stroke-width="1"/>`:''}
  <path d="M${48-g(20)%3} 53q5 -${2+g(21)%2} 9 0M${63+g(20)%3} 53q5 -${2+g(21)%2} 9 0" stroke="${hair}" stroke-width="2.6" fill="none" stroke-linecap="round"/><ellipse cx="52.5" cy="60" rx="2.6" ry="3" fill="#1a1210"/><ellipse cx="67.5" cy="60" rx="2.6" ry="3" fill="#1a1210"/><path d="M60 62q-3 7 0 9" stroke="${shade}" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M${53+g(22)%2} 77q7 ${3+g(23)%3} 14 0" stroke="#4a2a22" stroke-width="2.2" fill="none" stroke-linecap="round"/>
  ${beard?`<path d="M${60-rx+3} 66Q${60-rx+6} ${60+ry} 60 ${60+ry+1}Q${60+rx-6} ${60+ry} ${60+rx-3} 66" stroke="${hair}" stroke-width="3.2" fill="none" opacity=".85"/>`:''}</svg>`;}
let rosterSel=null;
const energyWord=e=>e>=80?'Fresh':e>=55?'Rested':e>=30?'Tired':'Exhausted',moraleWord=m=>m>=80?'Fired up':m>=60?'Content':m>=40?'Restless':'Unhappy';
function rosterCard(p){const r=E.ratings(p),b=E.bio(p),line=E.statLine(state,p),idx=state.players.indexOf(p),n=state.players.length;const ring=`conic-gradient(#b48aff ${r.ovr*3.6}deg,#ffffff14 0)`;
 const stars=k=>`<span class="stars" aria-label="${k} of 3 stars">${[1,2,3].map(i=>`<i class="${i<=k?'on':''}">★</i>`).join('')}</span>`;
 return `<section class="rv-hero" aria-live="polite"><button class="rv-arrow prev" data-action="rv-cycle" data-step="-1" aria-label="Previous player"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button>
 <div class="rv-portrait"><span class="rv-num" aria-hidden="true">${esc(p.number)}</span>${avatar(p,220)}<span class="rv-count">${idx+1} / ${n}</span></div>
 <div class="rv-main"><div class="rv-name"><span>${esc(p.name.split(' ').slice(0,-1).join(' '))}</span> <b>${esc(p.name.split(' ').slice(-1)[0])}</b><em>| ${esc(p.number)}</em></div>
  <div class="rv-row"><div class="rv-ovr"><span class="rv-tag">OVERALL</span><div class="ovr-ring" style="background:${ring}"><b>${r.ovr}</b></div></div>
  <div class="rv-arch"><span class="rv-tag">${esc(r.archetype.toUpperCase())}</span>${r.attrs.map(a=>`<div>${stars(a.stars)}<span>${a.name.toUpperCase()}</span></div>`).join('')}</div>
  <div class="rv-info">${[['POSITION',b.position.toUpperCase()+(b.assigned?'*':'')],['HEIGHT',b.height+(b.assigned?'*':'')],['ENERGY',energyWord(p.energy).toUpperCase()],['MORALE',moraleWord(p.morale).toUpperCase()],['CLASS',esc(p.year).toUpperCase()],['STATUS',p.injury?'INJURED':p.gpa<2?'INELIGIBLE':p.starter?'STARTER':p.minutes?'ROTATION':'BENCH']].map(([a,v])=>`<div><span class="rv-tag">${a}</span><strong>${v}</strong></div>`).join('')}</div></div>
  <div class="rv-stats">${[['PPG',line.ppg],['RPG',line.rpg],['APG',line.apg],['SPG',line.spg],['BPG',line.bpg],['FG%',line.fgp]].map(([a,v])=>`<div><strong>${v==null?'0.0':v.toFixed(1)}</strong><span>${a}</span></div>`).join('')}<small>${line.est?`Estimate from ${estSrc()} · no games played yet`:`Your season · ${line.gp} game${line.gp===1?'':'s'}`}</small></div></div>
 <div class="rv-side">${btn('Full profile','player','secondary small',`data-id="${p.id}"`)}<label class="rv-start"><input type="checkbox" data-starter="${p.id}" ${p.starter?'checked':''} ${state.match?'disabled':''}> Starter</label></div>
 <button class="rv-arrow next" data-action="rv-cycle" data-step="1" aria-label="Next player"><svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button></section>`;}

function roster(){const sum=state.players.reduce((s,p)=>s+p.minutes,0);
if(!state.players.some(p=>p.id===rosterSel))rosterSel=(state.players.find(p=>p.starter)||state.players[0])?.id;const sel=state.players.find(p=>p.id===rosterSel);const est=E.estimateLines(state);const assigned=state.players.some(p=>E.bio(p).assigned);
 const cell=v=>`<td class="grade g-${E.grade(v)[0]}">${E.grade(v)}</td>`;
 return `${header('THE PEOPLE BEHIND THE JERSEY','Roster & rotation','Set five starters and 160 minutes. Cycle through players with the arrows or ← →.')}
<div class="toolbar"><span>${pill(t('roster.spots',{n:state.players.length}))} ${pill(t('roster.minutes',{n:sum}),sum===160?'good':'warn')}</span>${btn(t('roster.auto'),'auto-lineup','primary')}</div>
${sel?rosterCard(sel):''}
 <div class="table-wrap rv-table"><div class="rv-team"><span>${esc(team().label.toUpperCase())} · LAKE WASHINGTON KANGS</span><span>W–L ${state.wins}–${state.losses} · TEAM CHEMISTRY ${Math.round(state.chemistry)}%</span></div><table>
<thead><tr>
<th>Start</th><th>Name</th><th>POS</th><th>YR</th><th class="ovr-col">OVR</th><th title="Inside scoring">INS</th><th title="Mid-range">MID</th><th title="Three-point">3PT</th><th title="Perimeter defense">PER D</th><th title="Interior defense">INS D</th><th>Energy</th><th>Min</th><th title="Games played">GP</th><th title="Points per game">PPG</th><th title="Rebounds per game">RPG</th><th title="Assists per game">APG</th><th title="Steals per game">SPG</th><th title="Blocks per game">BPG</th></tr></thead><tbody>
${
state.players.map(p=>{const r=E.ratings(p),b=E.bio(p),g=p.games?E.perGame(p):est[p.id];return `<tr class="${p.id===rosterSel?'selected':''} ${E.eligible(p)?'':'out'}" data-select="${p.id}"><td><input type="checkbox" data-starter="${p.id}" ${p.starter?'checked':''} aria-label="Start ${esc(p.name)}
" ${state.match?'disabled':''}></td><td><button class="player-cell" data-action="rv-select" data-id="${p.id}">${avatar(p,34)}<div><strong>${esc(p.name)}</strong><small>#${esc(p.number)}${
E.eligible(p)?'':` · <span class="warn-text">${p.injury?'Injured':p.gpa<2?'Ineligible':'Exhausted'}</span>`}
</small></div></button></td><td>${esc(b.position[0])}${b.assigned?'*':''}</td><td>${esc((p.year||'').slice(0,2).toUpperCase())}</td><td class="ovr-col"><b>${r.ovr}</b></td>${cell(r.ins)}${cell(r.mid)}${cell(r.tpt)}${cell(r.perd)}${cell(r.insd)}<td><span class="bar" aria-hidden="true"><i style="width:${p.energy}%"></i></span>${Math.round(p.energy)}</td><td>

<input class="minutes" type="number" min="0" max="32" step="1" value="${p.minutes}" data-minutes="${p.id}" aria-label="${esc(t('roster.minutesAria',{name:p.name}))}" ${state.match?'disabled':''}></td><td>${g.gp}</td><td class="${g.est?'est':''}"><b>${g.ppg.toFixed(1)}</b></td><td class="${g.est?'est':''}">${g.rpg.toFixed(1)}</td><td class="${g.est?'est':''}">${g.apg.toFixed(1)}</td><td class="${g.est?'est':''}">${g.spg.toFixed(1)}</td><td class="${g.est?'est':''}">${
g.bpg.toFixed(1)}
</td></tr>`}).join('')}</tbody></table></div>
 <p class="footnote"><span class="est-key">Italic</span> stats are estimates built from ${estSrc()}; they switch to your simulated stats once a player appears in a game.${assigned?' * Position or height not published, so the game estimates it.':''}</p>`;}
let practicePlan=[],practiceRun=null;
const PLAN_BLURB={shooting:'Repetition turns open looks into points. Builds skill but costs energy.',defense:'Move together. Sharpen fundamentals and build team chemistry.',recovery:'Help a simulated injury recover and restore energy for game day.',study:'Protect eligibility. Academic preparation is part of a healthy program.',bond:'A shared meal builds trust, morale and connection.'};
function planCap(){return Math.max(0,Math.min(3,state?.actions??0));}
function practice(){
practicePlan=practicePlan.filter(k=>E.plans[k]).slice(0,planCap());const cap=planCap(),full=practicePlan.length>=cap,locked=state.finished||!!state.match;
 const slots=[0,1,2].map(i=>{const k=practicePlan[i];if(i>=cap)return `<div class="plan-slot used"><span>SLOT ${i+1}</span><b>Used this week</b></div>`;return k?`<div class="plan-slot filled"><span>SLOT ${i+1}</span><b>${esc(E.plans[k].name)}</b><small>${esc(DRILLS[k].name)}</small><button class="plan-x" data-action="plan-toggle" data-plan="${k}" aria-label="Remove ${esc(E.plans[k].name)} from plan">${svg('<path d="M6 6l12 12M18 6L6 18"/>')}</button></div>`:`<div class="plan-slot open"><span>SLOT ${i+1}</span><b>Open</b><small>Pick a session below</small></div>`;}).join('');
 return `${header('DEVELOP THE WHOLE ATHLETE','Practice planner','Pick up to three sessions, then earn each one in a skill drill. Training is unlocked by skill, never bought.')}
<div class="toolbar"><label>${t('practice.group')} <select id="training-target"><option value="all">${t('practice.wholeTeam')}</option>${state.players.map(p=>`<option value="${p.id}" ${String(selected)===String(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${
pill(`${practicePlan.length} / ${cap} planned`)}
</div>
 <section class="practice-plan"><div class="plan-slots">${slots}</div><div class="plan-go">${btn(practicePlan.length?`Start practice → ${practicePlan.length} drill${practicePlan.length>1?'s':''}`:'Start practice →','practice-start','primary',practicePlan.length&&!locked?'':'disabled')}<small>${cap?'Pass a drill to unlock that session. Miss it and the slot stays open to retry.':'All three slots are used. Play the next game to reset them.'}</small></div></section>
 <div class="cards three">${Object.entries(E.plans).map(([key,p],i)=>
{const on=practicePlan.includes(key);return `<section class="card plan ${on?'in-plan':''}"><div class="plan-icon">
${svg(PLAN_ICONS[i])}</div><span class="eyebrow">
1 SLOT · SKILL CHECK</span>
<h2>${t(`plan.${key}.name`)}</h2><p>${
PLAN_BLURB[key]||''}
</p><div class="drill-chip">${svg('<path d="M12 3l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.4 6.8 19.1l1-5.8L3.5 9.2l5.9-.9z"/>')}${esc(DRILLS[key].name)}</div><details class="training-details"><summary>${t('practice.effects')}</summary><div class="effect-list"><span>${t('practice.fxSkill',{n:'+'+p.skill})}</span><span>${t('practice.fxEnergy',{n:sgn(p.energy)})}</span><span>${t('practice.fxMorale',{n:'+'+p.morale})}</span><span>${t('practice.fxGpa',{n:sgn(p.gpa.toFixed(2))})}</span><span>Perfect drill: ${p.skill?'+1 skill, ':''}+2 morale</span></div></details>${
btn(on?'✓ In plan · remove':full?'Plan full':'Add to plan','plan-toggle',on?'primary wide':'secondary wide',
`data-plan="${key}" aria-pressed="${on}" ${locked||(!on&&full)?'disabled':''}`)}</section>`;}).join('')}<section class="card purple"><span class="eyebrow">${tu('practice.planKicker')}</span><h2>${t('practice.planTitle')}</h2><p>${t('practice.planP1')}</p><p>
Every unlocked session is recorded in your decision trail and postgame breakdown.</p>
</section></div>`;}
function togglePlan(key){if(!E.plans[key])return;const i=practicePlan.indexOf(key);if(i>=0)practicePlan.splice(i,1);else{if(practicePlan.length>=planCap())throw Error(planCap()?'Your plan holds 3 sessions. Remove one first.':'No preparation slots left this week.');practicePlan.push(key);}render();}
function startPractice(){if(!practicePlan.length||practiceRun)return;practiceRun={queue:[...practicePlan],done:[],cleanup:null};nextDrill();}
function nextDrill(){const run=practiceRun;if(!run)return;run.cleanup?.();run.cleanup=null;const key=run.queue.shift();
 if(!key){practiceRun=null;practicePlan=practicePlan.filter(k=>!run.done.some(d=>d.key===k&&d.passed));if(modal.open)modal.close();render();const won=run.done.filter(d=>d.passed);notify(won.length?`${won.map(d=>E.plans[d.key].name).join(', ')} unlocked.${run.done.length>won.length?' Missed drills stay in your plan to retry.':''}`:'No sessions unlocked. Your slots are still open, so try again.',{type:won.length?'success':'warn',icon:'ball',title:won.length?`Practice complete · ${won.length} of ${run.done.length} unlocked`:'Practice not unlocked'});return;}
 const p=E.plans[key],left=run.queue.length;show(`<div class="drill-shell"><span class="eyebrow">PRACTICE · ${esc(p.name.toUpperCase())}${left?` · ${left} MORE AFTER THIS`:''}</span><div id="drill-root"></div></div>`);
 run.cleanup=mountDrill(modal.querySelector('#drill-root'),key,r=>{run.cleanup?.();run.cleanup=null;let msg;if(r.passed){try{E.train(state,key,selected,{perfect:r.perfect});save();msg=`${p.name} unlocked${r.perfect?' with a perfect drill bonus':''}. ${state.log[0]?.text||''}`;}catch(err){msg=err.message;r.passed=false;}}else msg=`${r.made} of ${r.total}. Not enough to unlock ${p.name}; the slot stays open.`;run.done.push({key,passed:r.passed});
  const root=modal.querySelector('#drill-root');if(root)root.innerHTML=`<div class="drill-result ${r.passed?'pass':'fail'}"><b>${r.passed?(r.perfect?'PERFECT':'UNLOCKED'):'NOT UNLOCKED'}</b><p>${esc(msg)}</p>${btn(run.queue.length?'Next drill →':'Finish practice','practice-next','primary')}</div>`;modal.querySelector('[data-action="practice-next"]')?.focus();});}

function recruit(){return `${header(tu('recruit.kicker'),t('nav.recruit'),t('recruit.intro'))}<div class="toolbar">${pill(t('roster.spots',{n:state.players.length}))}<span>${t('recruit.tokens',{n:formatNumber(state.tokens)})}</span></div><div class="cards three">${state.pool.map(p=>`<section class="card recruit"><div class="prospect-jersey" aria-hidden="true">${p.number}</div><span class="eyebrow">${tu('recruit.tryout',{pos:esc(tv(p.position))})}</span><h2>${esc(p.name)}</h2><div class="effect-list"><span>${t('roster.skill')} <b>${p.skill}</b></span><span>${t('roster.energy')} <b>${p.energy}</b></span><span>${t('roster.gpa')} <b>${p.gpa}</b></span></div>${btn(t('recruit.sign',{cost:p.cost}),'recruit','primary wide',`data-id="${p.id}" aria-label="${esc(t('recruit.signAria',{name:p.name,cost:p.cost}))}" ${state.players.length>=15||state.tokens<p.cost||state.finished||state.match?'disabled':''}`)}</section>`).join('')||`<section class="card">${t('recruit.none')}</section>`}</div>`;}
function office(){return `${header(tu('office.kicker'),t('nav.staff'),t('office.intro'))}<div class="cards two"><section class="card"><span class="eyebrow">${tu('office.weekly')}</span><h2>${t('office.title')}</h2><p>${t('office.body')}</p>${['listen','fundraise','academics'].map(key=>`<button class="choice" data-action="talk" data-choice="${key}" ${state.conversation||state.actions<1||state.finished||state.match?'disabled':''}><strong>${t(`office.${key}`)}</strong><span>${t(`office.${key}Fx`)}</span><b aria-hidden="true">→</b></button>`).join('')}</section><section class="card"><span class="eyebrow">${tu('office.assistantKicker')}</span><h2>${state.assistant?t(`staff.${state.assistant}.name`):t('office.buildStaff')}</h2><p>${t('office.assistantBody')}</p>${E.staff.map(a=>`<div class="staff-row"><div><strong>${t(`staff.${a.key}.name`)}</strong><small>${t(`staff.${a.key}.detail`)}</small></div>${btn(state.assistant===a.key?t('office.hired'):t('office.cost',{cost:a.cost}),'hire','small',`data-key="${a.key}" aria-label="${esc(t('office.hireAria',{name:t(`staff.${a.key}.name`),cost:a.cost}))}" ${state.assistant||state.finished||state.match?'disabled':''}`)}</div>`).join('')}${state.assistant?btn(t('office.dismiss'),'dismiss','text-button'):''}</section></div>${stage('short-arena')}`;}
function speedControls(){return `<div class="playback-controls"><span id="speed-label">${tu('game.speed')}</span><div role="group" aria-labelledby="speed-label" ${hint('speed')}>${[1,2,4].map(n=>btn(speedLabel(n),'speed',playbackSpeed===n?'selected':'',`data-speed="${n}" aria-pressed="${playbackSpeed===n}"`)).join('')}</div></div>`;}
function teamStats(stats,opp=''){if(!stats)return '';return `<div class="table-wrap team-compare"><table><thead><tr><th scope="col">${t('stats.title')}</th><th scope="col">${esc(up(t('game.kangs')))}</th><th scope="col">${esc(up(opp))}</th></tr></thead><tbody>${['rebounds','assists','steals','blocks'].map(k=>`<tr><td>${t(`stats.${k}`)}</td><td><b>${stats.home[k]}</b></td><td>${stats.away[k]}</td></tr>`).join('')}</tbody></table></div>`;}
function replayView(){const p=arena.presentation(),e=replayEvent;return `${header(tu('replay.kicker'),t('replay.title'),t('replay.intro'))}<div class="replay-layout">${stage('game-arena')}<div class="score-strip"><div>${tu('game.kangs')}<strong id="live-home">${p?.home??e.home}</strong></div><div class="clock"><span>${tu('replay.recorded')}</span><strong>#${e.number}</strong></div><div>${tu('game.visitors')}<strong id="live-away">${p?.away??e.visitor}</strong></div></div><p class="play-call"></p><div class="play-feed"></div>${speedControls()}${btn(t('replay.again'),'replay-again','primary')}${btn(arena.paused?t('replay.resume'):t('replay.pause'),'replay-pause','secondary',hint('playPause'))}${btn(t('replay.back'),'journal','secondary')}</div>`;}

function scoreBug(m,o){const q=m.possession>64?'OT':`Q${Math.max(1,Math.min(4,Math.ceil(m.possession/16)))}`,clock=`${Math.max(0,8-Math.floor((m.possession?((m.possession-1)%16)+1:0)/2))}:00`,P=state?plan():null,tag=P&&state.week>=P.cut?P.runName.toUpperCase():`${esc(team().label.toUpperCase())} · ${esc((o.type||'REGULAR SEASON').toUpperCase())}`,to=Math.max(0,m.timeouts??0);
 return `<div class="score-strip bug2k" role="group" aria-label="Scoreboard"><span class="bug-tag">${tag}</span><div class="bug-team home"><img src="${LOGO}" alt=""><div class="bug-name"><b>KANGS</b><small>${state.wins}–${state.losses} · <span class="bug-to" aria-label="${to} timeouts left">${[0,1,2].map(i=>`<i class="${i<to?'on':''}"></i>`).join('')}</span></small></div><strong id="live-home">${arena.presentation()?.home??m.home}</strong></div><div class="bug-mid"><span>${q}</span><strong>${clock}</strong><small>POSS ${m.possession}</small></div><div class="bug-team away"><strong id="live-away">${arena.presentation()?.away??m.away}</strong><div class="bug-name"><b>${esc(crestText(o.opponent))}</b><small>${esc(o.opponent)}</small></div>${oppMark(o.opponent,'bug-logo',`<span class="bug-crest">${esc(crestText(o.opponent)).slice(0,3)}</span>`)}</div><span class="bug-slogan">ALWAYS RISING</span></div>`;}

function game(){if(replayEvent)return replayView();if(state.finished&&!closingMatch)return endscreen();const o=closingMatch?state.results.at(-1):E.opponent(state),m=state.match||closingMatch,P=plan(),names=stages();return `${header(m?tu('game.liveKicker'):tu('game.prepKicker'),m?t('game.liveTitle'):t('game.vs',{opp:esc(o.opponent)}),`${esc(formatDate(o.date))} · ${esc(o.venue)} · ${state.week>=P.cut?t('game.eliminationGame',{run:names.run}):t('game.matchup',{type:esc(o.type?tv(o.type):t('game.typeDefault'))})}`)}<div class="game-layout"><div class="court-panel">${
stage('game-arena')}
${
m?`${scoreBug(m,o)}<p class="play-call" aria-live="polite">
${esc(arena.presentation()?.clip?shot(arena.presentation().clip):t('game.choosePlay'))}</p><details class="commentary-drawer"><summary>${t('game.playByPlay')}</summary><div class="play-feed">${(arena.isPlaying()?feedLines(m).slice(2):feedLines(m)).map((x,i)=>`<p class="${i===0?'new':''}">${esc(x)}</p>`).join('')||`<p>${t('game.crowdReady')}</p>`}</div></details>`:`<section class="card"><span class="eyebrow">${tu('game.scouting')}</span><h2>${esc(o.opponent)}</h2><p>
${hasScore(o)?`Reference result: Lake Washington ${o.points}–${o.against}.`:`Upcoming · ${esc(o.date)}${o.time?` · ${esc(o.time)}`:''} · ${o.home?'Home':'Away'} · ${esc(o.venue)}.`} Your result has not been written.</p>
<div class="effect-list"><span>${t('game.strength')} <b>${o.rating}</b></span><span>${t('game.style')} <b>${state.scouted?t(`style.${o.style}`):t('game.unscouted')}</b></span></div>${state.scouted?`<p class="notice">${t(`game.advice.${o.style}`)} ${t('game.adviceNote')}</p>`:btn(t('game.scout'),'scout','secondary')}</section>`}${m?`<details class="box-drawer"><summary>${t('game.boxScore')}</summary>${teamStats(m.stats,o.opponent)}${boxTable(m.line,up(t('game.kangs')),true)}</details>`:''}</div><aside class="right-rail" aria-label="${esc(t('game.controls'))}"><section class="card"><span class="eyebrow">${m?tu('game.sideline'):tu('game.startingFive')}</span>${m?`<h2>${t('game.callPlay')}</h2><label>${tu('game.system')}<select id="tactic">${['balanced','zone','pressure','perimeter'].map(v=>`<option value="${v}" ${m.tactic===v?'selected':''}>${t(`tactic.${v}`)}</option>`).join('')}</select></label><label>${tu('game.tempo')}<select id="pace">${['steady','fast'].map(v=>`<option value="${v}" ${m.pace===v?'selected':''}>${t(`pace.${v}`)}</option>`).join('')}</select></label>${speedControls()}${
btn(closingMatch?(arena.paused?t('game.resumeFinal'):t('game.pauseFinal')):auto?t('game.pause'):arena.paused?t('game.resume'):t('game.watch'),'auto','primary wide',hint('playPause'))}${btn(t('game.next'),'step','secondary wide',`${hint('nextPlay')} ${arena.isPlaying()||closingMatch?'disabled':''}`)}${btn(t('game.timeout',{n:m.timeouts}),'timeout','secondary wide',`${hint('timeout')} ${m.timeouts&&!closingMatch?'':'disabled'}`)}`:`<h2>${t('game.ready')}</h2>${state.players.filter(p=>p.starter).map(p=>`<div class="lineup-row"><span class="jersey">${p.number}</span><strong>${esc(p.name)}</strong><span>${t('game.minShort',{n:p.minutes})}</span></div>`).join('')}<p>${t('game.assigned',{n:state.players.reduce((s,p)=>s+p.minutes,0)})}</p>${btn(t('game.adjust'),'rotation','secondary wide')}${btn(t('game.tipOff'),'start-match','primary wide')}`}</section></aside></div>`;}
function locker(){return `${header(tu('locker.kicker'),t('nav.locker'),t('locker.intro'))}<div class="locker-layout">${stage('locker-arena')}<section class="card"><span class="eyebrow">${tu('locker.issue')}</span><h2>${t('locker.title')}</h2><div class="kit-options" role="group" aria-label="${esc(t('locker.kits'))}">${['home','away','alternate'].map(k=>`<button data-action="kit" data-kit="${k}" class="kit ${state.kit===k?'selected':''}" aria-pressed="${state.kit===k}"><div class="shirt ${k}" aria-hidden="true">K<br><b>11</b></div><strong>${t(`locker.${k}`)}</strong></button>`).join('')}</div><label>${t('locker.trim')}<input type="color" id="trim" value="${state.trim}"></label><p>${t('locker.note')}</p></section></div>`;}
function journal(){const teams={};for(const r of state.results){teams[r.opponent]??={name:r.opponent,w:0,l:0};r.won?teams[r.opponent].l++:teams[r.opponent].w++;}const ranks=Object.values(state.standings||{'Lake Washington':{name:'Lake Washington',w:state.wins,l:state.losses},...teams}).sort((a,b)=>b.w/Math.max(1,b.w+b.l)-a.w/Math.max(1,a.w+a.l));return `${header(tu('journal.kicker'),t('nav.season'),t('journal.intro'))}<div class="season-path" aria-label="${esc(t('journal.path'))}">${(P=>[['01',t('journal.regular'),state.week<P.stretch],['02',stages().stretch,state.week>=P.stretch&&state.week<P.cut],['03',stages().run,state.week>=P.cut]])(plan()).map(([n,l,cur],i)=>`${i?'<i aria-hidden="true">→</i>':''}<span class="${cur?'current':''}"${cur?' aria-current="step"':''}>${n} / ${l}</span>`).join('')}</div>${state.finished?`<section class="card purple"><span class="eyebrow">${state.champion?tu('journal.bannerYours'):tu('journal.teaches')}</span><h2>${state.champion?t('home.champions'):t('journal.whistle')}</h2><p>${t('journal.summary',{coach:esc(state.coach),w:state.wins,l:state.losses,fans:formatNumber(state.fans),chem:Math.round(state.chemistry)})}</p>${btn(t('journal.newSeason'),'new-season','secondary')}${btn(t('journal.export'),'export','secondary')}</section>`:''}<div class="cards two"><section class="card"><span class="eyebrow">${tu('journal.results')}</span><h2>${t('journal.scoreboard')}</h2>${state.results.map((r,i)=>`<button class="result-row" data-action="result" data-index="${i}"><b class="${r.won?'win':'loss'}">${r.won?'W':'L'}<span class="sr-only"> ${r.won?t('result.win'):t('result.loss')}</span></b><span>${esc(r.opponent)}<small>${esc(formatDate(r.date))}</small></span><strong>${r.home}–${r.away}</strong><span>${t('journal.replay')}</span></button>`).join('')||`<p>${t('journal.noGames')}</p>`}</section><section class="card"><span class="eyebrow">${tu('journal.standings')}</span><h2>${t('journal.table')}</h2><p>${t('journal.tableNote')}</p>${ranks.map((r,i)=>`<div class="staff-row"><span>${i+1}. ${esc(r.name)}</span><b>${r.w}–${r.l}</b></div>`).join('')}<h3>${t('journal.trail')}</h3><div class="journal-log">${state.log.map(l=>`<p><small>${tu('journal.gameN',{n:l.week})}</small>${esc(logText(l))}</p>`).join('')||`<p>${t('journal.trailEmpty')}</p>`}</div></section></div>`;}
function endscreen(){return `${header(tu('ending.kicker'),state.champion?t('ending.won'):t('ending.over'))} ${stage()}<section class="card ending"><h2>${state.champion?t('ending.bannerTitle'):t('ending.lossTitle')}</h2><p>${t('ending.record',{w:state.wins,l:state.losses})} ${state.champion?t('ending.championBody'):t('ending.lossBody')}</p>${btn(t('ending.story'),'journal','primary')}${btn(t('journal.newSeason'),'new-season','secondary')}</section>`;}
function dataView(){const levels=Object.entries(data.levels),rec=lv=>{const done=lv.games.filter(hasScore),left=lv.games.length-done.length;return done.length?`${done.filter(g=>g.points>g.against).length}–${done.filter(g=>g.points<g.against).length}${left?` · ${t('data.upcomingN',{n:left})}`:''}`:t('data.upcomingGames',{n:left});};
 return `${header(tu('data.kicker'),t('data.title'),t('data.intro',{season:esc(data.season)}))}<section class="card source-summary"><div>${pill(tu('data.badge'),'good')}<h2>${t('data.school')}</h2><p>${t('data.checked',{date:formatDateTime(data.checkedAt)})}</p><p>${levels.map(([k,lv])=>`${esc(teamName(k))} ${rec(lv)}`).join(' · ')}</p></div>${btn(t('data.refresh'),'refresh','secondary')}</section><p class="notice">${t('data.notice')}</p>${levels.map(([key,lv])=>`<h2 class="section-title">${esc(teamName(key))} · ${rec(lv)}</h2><div class="table-wrap"><table aria-label="${esc(teamName(key))}"><thead><tr><th scope="col">#</th><th scope="col">${t('data.player')}</th><th scope="col">${t('data.position')}</th><th scope="col">${t('data.height')}</th><th scope="col">${t('data.grade')}</th></tr></thead><tbody>${lv.players.map(p=>`<tr><td>${p.number}${p.numberAssigned?`<span class="muted" title="${esc(t('data.assignedTitle'))}">*</span>`:''}</td><td>${esc(p.name)}</td><td>${esc(tv(p.position))}</td><td>${esc(p.height)}</td><td>${esc(tv(p.year))}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${t('data.rosterNote',{season:esc(lv.rosterSeason||data.season)})}${lv.players.some(p=>p.numberAssigned)?` ${t('data.assignedNote')}`:''}</p><details class="schedule-drawer"><summary>${t('data.scheduleSummary',{team:esc(teamName(key)),season:esc(data.season),n:lv.games.length})}</summary><div class="table-wrap"><table aria-label="${esc(t('data.scheduleSummary',{team:teamName(key),season:data.season,n:lv.games.length}))}"><thead><tr><th scope="col">${t('data.date')}</th><th scope="col">${t('data.time')}</th><th scope="col">${t('data.opponent')}</th><th scope="col">${t('data.type')}</th><th scope="col">${t('data.score')}</th><th scope="col">${t('data.venue')}</th></tr></thead><tbody>${lv.games.map(g=>`<tr><td>${esc(formatDate(g.date))}</td><td>${esc(g.time||'')}</td><td>${t(g.home?'data.vs':'data.at')} ${oppBadge(g.opponent)}${esc(g.opponent)}</td><td>${esc(tv(g.type))}</td>${hasScore(g)?`<td class="${g.points>g.against?'good-text':'warn-text'}"><span aria-hidden="true">${g.points>g.against?'W':'L'}</span><span class="sr-only">${g.points>g.against?t('result.win'):t('result.loss')}</span> ${g.points}–${g.against}</td>`:`<td class="muted">${t('data.upcoming')}</td>`}<td>${esc(g.venue)}</td></tr>`).join('')}</tbody></table></div></details>${(o=>`<details class="schedule-drawer"><summary>${t('data.oppSummary',{team:esc(teamName(key)),real:o.filter(([,v])=>v.real).length,fiction:o.filter(([,v])=>!v.real).length})}</summary>${o.map(([n,v])=>`<p class="opp-roster"><b>${oppBadge(n)}${esc(n)}</b> <span class="muted">${t(v.real?'data.oppReal':'data.oppFictional')}</span><br>${v.players.map(x=>`#${x.number} ${esc(x.name)}`).join(' · ')}</p>`).join('')}</details>`)(Object.entries(lv.opponents||{}))}<p class="footnote"><a href="${esc(lv.source)}" target="_blank" rel="noreferrer">${t('data.openPage',{team:esc(teamName(key))})}<span class="sr-only"> (${t('a11y.newTab')})</span></a></p>`).join('')}`;}
